fn frame(t: i32) {
    let w: i32 = host::display::width();
    host::display::clear(0x0e0e14);
    if host::display::state_get(0) == 0 {
        host::mp::auto(6);
        host::display::state_set(0, 1);
    }
    if host::mp::connected() == 0 {
        host::display::draw_string(120, 230, "FINDING AN OPPONENT", 0x8899aa, 2);
    } else {
        let down: i32 = host::display::pointer_down();
        let prev: i32 = host::display::state_get(1);
        host::display::state_set(1, down);
        if down == 1 && prev == 0 {
            host::mp::send(1);
            host::display::state_set(2, host::display::state_get(2) + 1);
        }
        let mut evs: i32 = host::mp::event_count();
        while evs > 0 {
            let v: i32 = host::mp::event_next();
            if v == 1 {
                host::display::state_set(3, host::display::state_get(3) + 1);
            }
            evs = evs - 1;
        }
        let mine: i32 = host::display::state_get(2);
        let theirs: i32 = host::display::state_get(3);
        let mut knot: i32 = w / 2 + (mine - theirs) * 6;
        if knot < 40 {
            knot = 40;
        }
        if knot > w - 40 {
            knot = w - 40;
        }
        host::display::fill_rect(0, 240, w, 8, 0x554433);
        host::display::fill_rect(knot - 10, 220, 20, 48, 0xffffff);
        host::display::draw_string(30, 60, "YOU", 0xffcc33, 2);
        host::display::draw_number(30, 100, mine, 0xffcc33, 4);
        host::display::draw_string(400, 60, "THEM", 0x33ff88, 2);
        host::display::draw_number(400, 100, theirs, 0x33ff88, 4);
        host::display::draw_string(120, 420, "TAP FAST TO PULL THE KNOT", 0x8899aa, 1);
    }
    host::display::present();
}
